    { word: "dictionary", phonetic: "/ˈdɪkʃəneri/", def: "A book or electronic resource that lists words and gives their meaning.", defVn: "cuốn từ điển", pos: "noun", ex: ["Look up unknown words in an English-Vietnamese dictionary.", "An Oxford dictionary is a trusted study tool."], exVn: ["Tra cứu các từ chưa biết trong từ điển Anh - Việt nhé.", "Từ điển Oxford là công cụ học tập đáng tin cậy."] },
    { word: "pencil case", phonetic: "/ˈpensl keɪs/", def: "A small container for pens, pencils, and other stationery items.", defVn: "hộp bút, bóp viết", pos: "noun", ex: ["Keep your pens and rulers neatly inside your pencil case.", "She has a cute zippered pencil case."], exVn: ["Giữ bút và thước kẻ ngăn nắp trong hộp bút nhé.", "Cô ấy có một chiếc bóp viết kéo khóa rất dễ thương."] },
    { word: "calculator", phonetic: "/ˈkælkjuleɪtər/", def: "Something used for making mathematical calculations.", defVn: "máy tính bỏ túi, máy tính cầm tay", pos: "noun", ex: ["Scientific calculators are allowed in mathematics exams.", "Use the calculator to verify the sum."], exVn: ["Máy tính khoa học được phép mang vào phòng thi toán.", "Dùng máy tính để kiểm tra lại phép cộng nhé."] },
    { word: "homework", phonetic: "/ˈhoʊmwɜːrk/", def: "Schoolwork that a student is required to do at home.", defVn: "bài tập về nhà", pos: "noun", ex: ["Finish your English homework before dinner.", "Doing homework helps reinforce what you learned."], exVn: ["Hãy hoàn thành bài tập về nhà tiếng Anh trước bữa tối nhé.", "Làm bài tập giúp củng cố những gì bạn đã học."] },
    { word: "exam", phonetic: "/ɪɡˈzæm/", def: "A formal test of a person's knowledge or proficiency in a subject.", defVn: "kỳ thi, bài thi", pos: "noun", ex: ["She studied diligently and passed the English exam with flying colors.", "The midterm exam is next Tuesday."], exVn: ["Cô ấy đã học tập chăm chỉ và vượt qua kỳ thi tiếng Anh với điểm số xuất sắc.", "Kỳ thi giữa kỳ vào thứ Ba tuần sau."] },
    { word: "lesson", phonetic: "/ˈlesn/", def: "A period of learning or teaching.", defVn: "bài học, tiết học", pos: "noun", ex: ["Today's English lesson is about daily routines.", "Listen attentively throughout the 45-minute lesson."], exVn: ["Bài học tiếng Anh hôm nay nói về thói quen hàng ngày.", "Hãy chăm chú lắng nghe trong suốt tiết học 45 phút."] },
    { word: "grade", phonetic: "/ɡreɪd/", def: "A mark indicating the quality of a student's work; a year of school.", defVn: "điểm số, khối lớp", pos: "noun", ex: ["He received an 'A' grade on his English presentation.", "My younger sister is in grade 5."], exVn: ["Cậu ấy đạt điểm A trong bài thuyết trình tiếng Anh.", "Em gái tôi đang học lớp 5."] },
    { word: "recess", phonetic: "/ˈriːses/", def: "A break between school classes.", defVn: "giờ ra chơi, giờ giải lao ở trường", pos: "noun", ex: ["Students play games and eat snacks during recess.", "The bell rang signaling recess time."], exVn: ["Học sinh chơi trò chơi và ăn nhẹ trong giờ ra chơi.", "Chuông reo báo hiệu giờ giải lao."] },
    { word: "subject", phonetic: "/ˈsʌbdʒɪkt/", def: "A branch of knowledge studied or taught in a system, such as school.", defVn: "môn học (ở trường)", pos: "noun", ex: ["English and Science are my favorite school subjects.", "How many subjects are you studying this semester?"], exVn: ["Tiếng Anh và Khoa học là những môn học yêu thích nhất của tôi.", "Học kỳ này bạn đang học bao nhiêu môn?"] },
    { word: "sharpener", phonetic: "/ˈʃɑːrpnər/", def: "A device for sharpening pencils.", defVn: "cái gọt bút chì, chuốt bút chì", pos: "noun", ex: ["Sharpen your blunt pencil with a pencil sharpener.", "I keep a small sharpener in my pencil case."], exVn: ["Gọt chiếc bút chì cùn bằng cái gọt bút chì nhé.", "Tôi để một cái chuốt bút chì nhỏ trong hộp bút."] },
    { word: "marker", phonetic: "/ˈmɑːrkər/", def: "A felt-tipped pen with a broad tip.", defVn: "bút dạ quang, bút lông viết bảng", pos: "noun", ex: ["Highlight key vocabulary terms with a yellow marker.", "The teacher wrote with a blue whiteboard marker."], exVn: ["Tô sáng các thuật ngữ từ vựng quan trọng bằng bút dạ quang vàng.", "Thầy giáo đã viết bằng bút lông bảng màu xanh."] }
