    { word: "leaf", phonetic: "/liːf/", def: "A flattened structure of a higher plant, typically green and blade-like (plural: leaves).", defVn: "chiếc lá, lá cây (số nhiều: leaves)", pos: "noun", ex: ["Golden leaves fall from trees in autumn.", "Tea is made from dried green leaves."], exVn: ["Những chiếc lá vàng rơi rụng khỏi cành cây vào mùa thu.", "Trà được làm từ những chiếc lá xanh phơi khô."] },
    { word: "root", phonetic: "/ruːt/", def: "The part of a plant which attaches it to the ground, conveying water and nourishment.", defVn: "rễ cây, cội rễ", pos: "noun", ex: ["Deep roots help large trees stand strong in storms.", "Carrots are nutritious edible roots."], exVn: ["Rễ sâu giúp cây to đứng vững vàng trong bão gió.", "Cà rốt là loại rễ củ ăn được rất bổ dưỡng."] },
    { word: "seed", phonetic: "/siːd/", def: "The unit of reproduction of a flowering plant, capable of developing into another plant.", defVn: "hạt giống, hạt", pos: "noun", ex: ["Plant the sunflower seed in fertile soil.", "Chia seeds and sunflower seeds are healthy snacks."], exVn: ["Hãy gieo hạt hoa hướng dương vào đất màu mỡ nhé.", "Hạt chia và hạt hướng dương là những món ăn nhẹ lành mạnh."] },
    { word: "mango", phonetic: "/ˈmæŋɡoʊ/", def: "A fleshy oval yellowish-red tropical fruit that is eaten ripe or used green in pickles.", defVn: "quả xoài", pos: "noun", ex: ["Sweet ripe mango is delicious in summer desserts.", "Green mango with chili salt is a favorite snack in Vietnam."], exVn: ["Xoài chín ngọt rất thơm ngon trong các món tráng miệng mùa hè.", "Xoài xanh chấm muối ớt là món ăn vặt được yêu thích ở Việt Nam."] },
    { word: "lemon", phonetic: "/ˈlemən/", def: "A yellow oval citrus fruit with thick skin and fragrant, sour juice.", defVn: "quả chanh vàng (vị chua)", pos: "noun", ex: ["Add a slice of fresh lemon to your warm honey tea.", "Lemon juice contains high levels of Vitamin C."], exVn: ["Thêm một lát chanh tươi vào tách trà mật ong ấm nhé.", "Nước cốt chanh chứa hàm lượng Vitamin C cao."] },
    { word: "lime", phonetic: "/laɪm/", def: "A rounded citrus fruit similar to a lemon but smaller, greener, and more acid.", defVn: "quả chanh xanh (chanh ta)", pos: "noun", ex: ["Squeeze fresh lime over your bowl of hot pho.", "Lime juice gives a refreshing tangy kick."], exVn: ["Vắt chanh xanh tươi vào tô phở nóng hổi nhé.", "Nước chanh xanh mang lại vị chua thanh sảng khoái."] },
    { word: "grape", phonetic: "/ɡreɪp/", def: "A berry growing in clusters on a grapevine, eaten raw or used for making wine.", defVn: "quả nho, chùm nho", pos: "noun", ex: ["Sweet seedless green grapes are crisp and delicious.", "Ninh Thuan is famous for its lush grape vineyards."], exVn: ["Những quả nho xanh ngọt không hạt rất giòn và ngon.", "Ninh Thuận nổi tiếng với những vườn nho trĩu quả."] },
    { word: "strawberry", phonetic: "/ˈstrɔːberi/", def: "A sweet soft red fruit with a seed-studded surface.", defVn: "quả dâu tây", pos: "noun", ex: ["Da Lat is famous for fresh and fragrant red strawberries.", "She topped her yogurt with sliced strawberries."], exVn: ["Đà Lạt nổi tiếng với những quả dâu tây đỏ tươi thơm lừng.", "Cô ấy rắc dâu tây cắt lát lên sữa chua."] },
    { word: "watermelon", phonetic: "/ˈwɔːtərmelən/", def: "The large fruit of a plant of the gourd family, with smooth green skin and juicy red pulp.", defVn: "quả dưa hấu", pos: "noun", ex: ["Chilled watermelon is the perfect treat on hot summer days.", "Watermelon is over 90 percent water."], exVn: ["Dưa hấu ướp lạnh là món quà hoàn hảo vào những ngày hè nóng nực.", "Dưa hấu chứa hơn 90 phần trăm là nước."] },
    { word: "pineapple", phonetic: "/ˈpaɪnæpl/", def: "A large juicy tropical fruit consisting of aromatic edible yellow flesh surrounded by a tough segmented skin.", defVn: "quả dứa, quả thơm, quả khóm", pos: "noun", ex: ["Fresh pineapple juice is sweet and tangy.", "Pineapple is rich in bromelain and aids digestion."], exVn: ["Nước ép dứa tươi có vị chua ngọt thanh mát.", "Quả dứa rất giàu bromelain và hỗ trợ tiêu hóa."] },
    { word: "coconut", phonetic: "/ˈkoʊkənʌt/", def: "The large, oval, brown seed of a tropical palm, containing edible white meat and clear liquid.", defVn: "quả dừa, trái dừa", pos: "noun", ex: ["Fresh coconut water is natural, refreshing, and full of electrolytes.", "Ben Tre is the land of coconuts in Vietnam."], exVn: ["Nước dừa tươi rất tự nhiên, giải khát và đầy khoáng chất.", "Bến Tre là xứ sở dừa của Việt Nam."] },
    { word: "papaya", phonetic: "/pəˈpaɪə/", def: "A tropical fruit shaped like an elongated melon, with edible orange flesh and small black seeds.", defVn: "quả đu đủ", pos: "noun", ex: ["Sweet ripe papaya is gentle on the stomach.", "Green papaya salad with dried beef is a street classic."], exVn: ["Đu đủ chín ngọt rất lành bụng và dễ tiêu.", "Nộm đu đủ xanh bò khô là món ăn đường phố kinh điển."] },
    { word: "potato", phonetic: "/pəˈteɪtoʊ/", def: "A starchy plant tuber that is one of the most important food crops.", defVn: "củ khoai tây", pos: "noun", ex: ["Mashed potatoes with butter taste creamy and delicious.", "Bake the potatoes in the oven until golden."], exVn: ["Khoai tây nghiền với bơ có vị béo ngậy và thơm ngon.", "Nướng khoai tây trong lò cho đến khi vàng ươm."] },
    { word: "tomato", phonetic: "/təˈmeɪtoʊ/", def: "A glossy red or yellowish pulpy edible fruit that is typically eaten as a vegetable in salads.", defVn: "quả cà chua", pos: "noun", ex: ["Fresh red tomatoes are rich in lycopene and antioxidants.", "Slice the tomatoes for the garden salad."], exVn: ["Cà chua đỏ tươi rất giàu lycopene và chất chống oxy hóa.", "Thái lát cà chua cho món salad vườn nhé."] },
    { word: "carrot", phonetic: "/ˈkærət/", def: "A tapering orange-colored root eaten as a vegetable.", defVn: "củ cà rốt", pos: "noun", ex: ["Eating crunchy carrots is great for your eyesight.", "Add diced carrots to the chicken soup."], exVn: ["Ăn cà rốt giòn rất tốt cho thị lực của bạn.", "Thêm cà rốt thái hạt lựu vào súp gà nhé."] },
    { word: "onion", phonetic: "/ˈʌnjən/", def: "A swollen edible bulb with a pungent taste and smell, composed of several concentric layers.", defVn: "củ hành tây", pos: "noun", ex: ["Sauté chopped onions in olive oil until fragrant.", "Cutting raw onions may make your eyes water."], exVn: ["Xào hành tây băm với dầu ô liu cho đến khi dậy mùi thơm.", "Cắt hành tây sống có thể làm bạn cay mắt."] },
    { word: "garlic", phonetic: "/ˈɡɑːrlɪk/", def: "A strong-smelling pungent-tasting bulb, used as a flavoring in cookery and in herbal medicine.", defVn: "củ tỏi (gia vị)", pos: "noun", ex: ["Garlic boosts your immune system and adds rich flavor to food.", "Crush two cloves of fresh garlic."], exVn: ["Tỏi giúp tăng cường hệ miễn dịch và tăng hương vị đậm đà cho món ăn.", "Đập dập hai tép tỏi tươi nhé."] },
    { word: "cucumber", phonetic: "/ˈkjuːkʌmbər/", def: "A long, green-skinned fruit with watery flesh, usually eaten raw in salads or pickled.", defVn: "quả dưa chuột, dưa leo", pos: "noun", ex: ["Cool sliced cucumbers are crunchy and hydrating.", "Place cucumber slices on your eyes to relax."], exVn: ["Dưa chuột thái lát mát lạnh rất giòn và cấp nước tốt.", "Đắp những lát dưa chuột lên mắt để thư giãn nhé."] },
    { word: "vegetable", phonetic: "/ˈvedʒtəbl/", def: "A plant or part of a plant used as food.", defVn: "rau củ, rau xanh", pos: "noun", ex: ["Eating plenty of green vegetables keeps your body healthy.", "Buy fresh organic vegetables at the market."], exVn: ["Ăn nhiều rau xanh giúp cơ thể luôn khỏe mạnh.", "Mua rau củ hữu cơ tươi ở chợ nhé."] }
