    { word: "glass", phonetic: "/ɡlæs/", def: "A drinking container made of glass.", defVn: "ly thủy tinh, cốc thủy tinh", pos: "noun", ex: ["Drink a tall glass of fresh orange juice.", "She filled the glass with cold water."], exVn: ["Hãy uống một ly nước cam tươi lớn nhé.", "Cô ấy rót đầy nước lạnh vào chiếc ly thủy tinh."] },
    { word: "bottle", phonetic: "/ˈbɑːtl/", def: "A container with a narrow neck, used for storing drinks or other liquids.", defVn: "chai, bình đựng nước", pos: "noun", ex: ["Carry a reusable water bottle when traveling.", "A glass bottle of milk was delivered to the doorstep."], exVn: ["Mang theo bình nước dùng nhiều lần khi đi du lịch nhé.", "Một chai sữa thủy tinh đã được giao đến trước hiên nhà."] },
    { word: "kettle", phonetic: "/ˈketl/", def: "A container or device in which water is boiled, having a lid, spout, and handle.", defVn: "ấm đun nước", pos: "noun", ex: ["Boil fresh water in the electric kettle for tea.", "The stainless steel kettle whistled on the stove."], exVn: ["Đun nước sôi trong ấm điện để pha trà nhé.", "Chiếc ấm inox reo lên trên bếp."] },
    { word: "stove", phonetic: "/stoʊv/", def: "An apparatus for cooking or heating that operates by burning fuel or using electricity.", defVn: "bếp nấu (bếp gas, bếp từ)", pos: "noun", ex: ["Turn off the gas stove after you finish cooking.", "Induction stoves are safe, fast, and easy to wipe clean."], exVn: ["Tắt bếp gas sau khi bạn nấu ăn xong nhé.", "Bếp từ rất an toàn, nấu nhanh và dễ lau chùi."] },
    { word: "oven", phonetic: "/ˈʌvn/", def: "An enclosed compartment for cooking and heating food.", defVn: "lò nướng (bánh, thịt)", pos: "noun", ex: ["Preheat the oven to 180 degrees before baking cookies.", "The roast chicken smells delicious in the oven."], exVn: ["Làm nóng lò nướng đến 180 độ trước khi nướng bánh quy nhé.", "Món gà quay thơm phức trong lò nướng."] },
    { word: "microwave", phonetic: "/ˈmaɪkrəweɪv/", def: "An oven that uses microwaves to cook or heat food quickly.", defVn: "lò vi sóng", pos: "noun", ex: ["Warm up your soup in the microwave for two minutes.", "Use microwave-safe bowls when reheating food."], exVn: ["Làm nóng súp trong lò vi sóng trong hai phút nhé.", "Sử dụng bát an toàn cho lò vi sóng khi hâm nóng thức ăn."] },
    { word: "cutting board", phonetic: "/ˈkʌtɪŋ bɔːrd/", def: "A durable board on which to place material for cutting.", defVn: "thớt (thái thịt, rau)", pos: "noun", ex: ["Use separate cutting boards for raw meat and vegetables.", "Wash the wooden cutting board thoroughly."], exVn: ["Dùng thớt riêng cho thịt sống và rau củ nhé.", "Rửa sạch thớt gỗ thật kỹ lưỡng."] },
    { word: "sink", phonetic: "/sɪŋk/", def: "A fixed basin with a water supply and a drain.", defVn: "bồn rửa bát, bồn rửa tay", pos: "noun", ex: ["Wash the greasy plates in the kitchen sink.", "Keep the kitchen sink clean and unclogged."], exVn: ["Rửa những chiếc đĩa dính dầu mỡ trong bồn rửa bát nhé.", "Giữ bồn rửa chén luôn sạch sẽ và thông thoáng."] },
    { word: "cook", phonetic: "/kʊk/", def: "Prepare food, a dish, or a meal by combining and heating the ingredients in various ways.", defVn: "nấu ăn, nấu nướng", pos: "verb", ex: ["I love to cook healthy home meals for my family.", "Mom is cooking traditional beef pho in the kitchen."], exVn: ["Tôi rất thích tự nấu những bữa cơm gia đình bổ dưỡng cho người thân.", "Mẹ đang nấu phở bò truyền thống trong bếp."] },
    { word: "bake", phonetic: "/beɪk/", def: "Cook food by dry heat without direct exposure to a flame, typically in an oven.", defVn: "nướng bánh (bằng lò)", pos: "verb", ex: ["Let's bake fresh chocolate chip cookies this Sunday.", "She baked a fluffy birthday cake for her brother."], exVn: ["Cùng nướng bánh quy sô cô la thơm lừng vào Chủ Nhật này nhé.", "Cô ấy đã nướng một chiếc bánh sinh nhật mềm xốp cho anh trai."] }
