    { word: "keyboard", phonetic: "/ˈkiːbɔːrd/", def: "A panel of keys that operate a computer or typewriter.", defVn: "bàn phím máy tính", pos: "noun", ex: ["Learn touch typing to type faster on your keyboard.", "She typed her English homework smoothly on the keyboard."], exVn: ["Học gõ 10 ngón để gõ nhanh hơn trên bàn phím nhé.", "Cô ấy gõ bài tập tiếng Anh thoăn thoắt trên bàn phím."] },
    { word: "mouse", phonetic: "/maʊs/", def: "A small handheld device that is dragged across a flat surface to move the cursor on a computer screen.", defVn: "con chuột máy tính", pos: "noun", ex: ["Click the left mouse button to open the application.", "A wireless ergonomic mouse is comfortable to use."], exVn: ["Nhấp chuột trái để mở ứng dụng nhé.", "Con chuột công thái học không dây dùng rất thoải mái."] },
    { word: "printer", phonetic: "/ˈprɪntər/", def: "A machine for printing text or pictures onto paper, especially one linked to a computer.", defVn: "máy in (tài liệu)", pos: "noun", ex: ["Print two copies of the contract on the color printer.", "The office printer ran out of white paper."], exVn: ["In hai bản hợp đồng trên máy in màu nhé.", "Máy in văn phòng vừa hết giấy trắng rồi."] },
    { word: "paper", phonetic: "/ˈpeɪpər/", def: "Material manufactured in thin sheets from the pulp of wood, used for writing or printing.", defVn: "tờ giấy, giấy in", pos: "noun", ex: ["Load a ream of A4 paper into the printer tray.", "Write down your ideas on a clean sheet of paper."], exVn: ["Nạp một ram giấy A4 vào khay máy in nhé.", "Hãy ghi lại những ý tưởng của bạn lên một tờ giấy trắng."] },
    { word: "file", phonetic: "/faɪl/", def: "A folder or collection of information stored on a computer under a single name.", defVn: "tệp tin, hồ sơ dữ liệu", pos: "noun", ex: ["Save your file regularly so you don't lose progress.", "Attach the PDF file to your email message."], exVn: ["Hãy lưu tệp tin thường xuyên để không bị mất dữ liệu nhé.", "Đính kèm tệp PDF vào thư email của bạn."] },
    { word: "email", phonetic: "/ˈiːmeɪl/", def: "Messages distributed by electronic means from one computer user to one or more recipients.", defVn: "thư điện tử, email", pos: "noun", ex: ["Send me an email with the project details.", "Check your email inbox every morning."], exVn: ["Gửi email cho tôi kèm thông tin chi tiết dự án nhé.", "Kiểm tra hộp thư email mỗi sáng nhé."] },
    { word: "internet", phonetic: "/ˈɪntərnet/", def: "A global computer network providing a variety of information and communication facilities.", defVn: "mạng in-tơ-nét, mạng toàn cầu", pos: "noun", ex: ["The internet allows us to learn English from anywhere.", "We search for information on the internet every day."], exVn: ["Mạng internet cho phép chúng ta học tiếng Anh từ bất cứ đâu.", "Chúng ta tìm kiếm thông tin trên internet mỗi ngày."] },
    { word: "website", phonetic: "/ˈwebsaɪt/", def: "A set of related web pages located under a single domain name.", defVn: "trang web, trang thông tin điện tử", pos: "noun", ex: ["Bookmark this English learning website on your browser.", "Our company website has an intuitive design."], exVn: ["Đánh dấu trang web học tiếng Anh này trên trình duyệt nhé.", "Trang web của công ty chúng tôi có thiết kế rất trực quan."] },
    { word: "password", phonetic: "/ˈpæswɜːrd/", def: "A secret word or phrase that must be used to gain admission to a system.", defVn: "mật khẩu, mã bảo vệ", pos: "noun", ex: ["Create a strong password with letters, numbers, and symbols.", "Never share your private password with anyone."], exVn: ["Tạo một mật khẩu mạnh kết hợp chữ cái, số và ký tự đặc biệt nhé.", "Không bao giờ chia sẻ mật khẩu riêng tư của bạn cho bất kỳ ai."] },
    { word: "wifi", phonetic: "/ˈwaɪ faɪ/", def: "A facility allowing computers, smartphones, or other devices to connect to the internet wirelessly.", defVn: "mạng không dây, sóng Wi-Fi", pos: "noun", ex: ["What is the Wi-Fi password for this coffee shop?", "Connect to the free high-speed Wi-Fi network."], exVn: ["Mật khẩu Wi-Fi của quán cà phê này là gì vậy?", "Kết nối với mạng Wi-Fi tốc độ cao miễn phí nhé."] },
    { word: "message", phonetic: "/ˈmesɪdʒ/", def: "A verbal, written, or recorded communication sent to or left for a recipient.", defVn: "tin nhắn, thông điệp", pos: "noun", ex: ["I received a friendly text message from my teacher.", "Send a message when you arrive safely."], exVn: ["Tôi đã nhận được một tin nhắn thân thiện từ giáo viên.", "Gửi tin nhắn khi bạn đã đến nơi an toàn nhé."] },
    { word: "call", phonetic: "/kɔːl/", def: "An act of telephoning someone.", defVn: "cuộc gọi (điện thoại)", pos: "noun", ex: ["I missed a phone call from my manager.", "Give me a video call this evening."], exVn: ["Tôi đã lỡ một cuộc gọi từ người quản lý.", "Gọi video cho tôi tối nay nhé."] },
    { word: "meeting", phonetic: "/ˈmiːtɪŋ/", def: "An assembly of people for a particular purpose, especially formal discussion.", defVn: "cuộc họp, buổi họp", pos: "noun", ex: ["We have an online team meeting at 9:00 AM.", "The meeting ended with productive results."], exVn: ["Chúng tôi có cuộc họp nhóm trực tuyến lúc 9h sáng.", "Cuộc họp đã kết thúc với những kết quả rất hiệu quả."] },
    { word: "project", phonetic: "/ˈprɑːdʒekt/", def: "An enterprise that is carefully planned to achieve a particular aim.", defVn: "dự án, đề án", pos: "noun", ex: ["Our team is working on an innovative AI project.", "She submitted her final English project on time."], exVn: ["Nhóm chúng tôi đang thực hiện một dự án AI đổi mới sáng tạo.", "Cô ấy đã nộp dự án tiếng Anh cuối khóa đúng hạn."] },
    { word: "colleague", phonetic: "/ˈkɑːliːɡ/", def: "A person with whom one works in a profession or business.", defVn: "đồng nghiệp (cùng cơ quan)", pos: "noun", ex: ["My colleagues are supportive and friendly.", "Collaborate closely with your teammates and colleagues."], exVn: ["Các đồng nghiệp của tôi rất nhiệt tình giúp đỡ và thân thiện.", "Hợp tác chặt chẽ với các bạn trong nhóm và đồng nghiệp nhé."] },
    { word: "desk", phonetic: "/desk/", def: "A piece of furniture with a flat surface for working at in an office.", defVn: "bàn làm việc", pos: "noun", ex: ["Keep your office desk clean, organized, and clutter-free.", "She decorated her desk with a small green succulent."], exVn: ["Giữ bàn làm việc văn phòng luôn sạch sẽ, ngăn nắp và gọn gàng nhé.", "Cô ấy trang trí bàn làm việc bằng một cây sen đá nhỏ."] }
